export class PushTokenStore{constructor(){this.map=new Map()} upsert({userId,deviceId,token,platform,now=Date.now()}){if(!userId||!deviceId||!token)throw new Error('PUSH_TOKEN_FIELDS_REQUIRED');const k=`${userId}::${deviceId}`;const row={userId,deviceId,token,platform,status:'ACTIVE',updatedAt:now};this.map.set(k,row);return row} invalidate(userId,deviceId,{reason='PROVIDER_INVALID',now=Date.now()}={}){const k=`${userId}::${deviceId}`,r=this.map.get(k);if(!r)return null;const n={...r,status:'INVALID',invalidReason:reason,updatedAt:now};this.map.set(k,n);return n} active(userId){return [...this.map.values()].filter(x=>x.userId===userId&&x.status==='ACTIVE')}}
